                                                .mediaType(MediaType.APPLICATION_JSON_VALUE)
                                                .schema(schemaBuilder().implementation(UpgradeFromUriRequest.class))))
                                .response(responseBuilder().implementation(Plugin.class)))
                .POST(
                        "plugins/{name}/upgrade",
