                        this::upgrade,
                        builder -> builder.operationId("UpgradePlugin")
                                .description("Upgrade a plugin by uploading a Jar file")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the plugin to upgrade.")
                                        .in(ParameterIn.PATH)
