                                        .content(contentBuilder()
                                                .mediaType(MediaType.MULTIPART_FORM_DATA_VALUE)
                                                .schema(schemaBuilder().implementation(InstallRequest.class))))
                                .response(responseBuilder().implementation(Plugin.class)))
                .PUT(
