16	    /** Label to mark an extension resource should not be overwritten during initialization. */
17	    public static final String DO_NOT_OVERWRITE_LABEL = "halo.run/do-not-overwrite";
18	
19	    /**
20	     * Check if the extension has the do-not-overwrite label. If the label is present and set to true, it indicates that
21	     * the extension should not be overwritten during initialization.
22	     *
23	     * @param extension the extension
24	     * @return true if it has the label, false otherwise
25	     */
26	    public static boolean hasDoNotOverwriteLabel(ExtensionOperator extension) {
27	        if (extension.getMetadata() == null) {
28	            return false;
29	        }
30	        var labels = extension.getMetadata().getLabels();
31	        return labels != null && Boolean.parseBoolean(labels.get(DO_NOT_OVERWRITE_LABEL));
32	    }
