38	    public static boolean addFinalizers(MetadataOperator metadata, Set<String> finalizers) {
39	        var modifiableFinalizers =
40	                new HashSet<>(metadata.getFinalizers() == null ? Collections.emptySet() : metadata.getFinalizers());
41	        var added = modifiableFinalizers.addAll(finalizers);
42	        if (added) {
43	            metadata.setFinalizers(modifiableFinalizers);
44	        }
45	        return added;
46	    }
47	
48	    public static boolean removeFinalizers(MetadataOperator metadata, Set<String> finalizers) {
49	        if (metadata.getFinalizers() == null) {
50	            return false;
51	        }
52	        var existingFinalizers = new HashSet<>(metadata.getFinalizers());
53	        var removed = existingFinalizers.removeAll(finalizers);
54	        if (removed) {
55	            metadata.setFinalizers(existingFinalizers);
56	        }
57	        return removed;
58	    }
59	
60	    /**
61	     * Query for not deleting.
62	     *
63	     * @return Query
64	     */
65	    @SuppressWarnings("removal")
66	    public static Query notDeleting() {
67	        return Queries.isNull("metadata.deletionTimestamp");
68	    }
69	
70	    /**
71	     * Default sort by creation timestamp desc and name asc.
72	     *
73	     * @return Sort
74	     */
75	    public static Sort defaultSort() {
76	        return Sort.by(desc("metadata.creationTimestamp"), asc("metadata.name"));
77	    }
78	}
